    @Override
    public Optional<IUserInputHandler> handleUserInput(Screen screen, UserInput input, IInternalKeyMappings keyBindings) {
        double mouseY;
        if (!this.controller.isActive(this)) {
            return Optional.empty();
        }
        Optional<IUserInputHandler> transferButtonHandler = this.transferButtonInputHandler.handleUserInput(screen, input, keyBindings);
        if (transferButtonHandler.isPresent()) {
            return transferButtonHandler;
        }
        boolean leftClick = input.getKey().equals((Object)LEFT_MOUSE_BUTTON);
        boolean rightClick = input.getKey().equals((Object)RIGHT_MOUSE_BUTTON);
        if (!leftClick && !rightClick) {
            return Optional.empty();
        }
        double mouseX = input.getMouseX();
        if (!this.isMouseOver(mouseX, mouseY = input.getMouseY())) {
            return Optional.empty();
        }
        if (this.drawable.getSlotUnderMouse(mouseX, mouseY).isEmpty()) {
            return Optional.of(this);
        }
        IClickableIngredientInternal ingredient = this.getClickableIngredientUnderMouse(mouseX, mouseY).orElse(null);
        if (ingredient == null) {
            return Optional.of(this);
        }
        if (!input.isSimulate()) {
            List<RecipeIngredientRole> roles = leftClick ? List.of(RecipeIngredientRole.OUTPUT) : List.of(RecipeIngredientRole.INPUT, RecipeIngredientRole.CATALYST);
            IJeiRuntime jeiRuntime = Internal.getJeiRuntime();
            FocusUtil focusUtil = new FocusUtil(jeiRuntime.getJeiHelpers().getFocusFactory(), Internal.getJeiClientConfigs().getClientConfig(), jeiRuntime.getIngredientManager());
            ingredient.show(jeiRuntime.getRecipesGui(), focusUtil, roles);
            this.controller.hide();
        }
        return Optional.of(new SameElementInputHandler(this, ingredient::isMouseOver));
    }
}

