public Optional<IUserInputHandler> handleUserInput(Screen screen, UserInput input, IInternalKeyMappings keyBindings) {
    if (!input.is(keyBindings.getLeftClick())) {
        return Optional.empty();
    }
    if (!input.isSimulate()) {
        boolean wasDragging = this.scrollbar.isDragging();
        this.scrollbar.stopDrag();
        if (wasDragging) {
            return Optional.of(this);
        }
        return Optional.empty();
    }
    if (!this.controller.canScroll()) {
        return Optional.empty();
    }
    Scrollbar.ScrollResult result = this.scrollbar.startDrag(input.getMouseX(), input.getMouseY(), this.controller.getVisibleScrollAmount(), this.controller.getHiddenScrollAmount(), this.controller.getScrollOffsetY());
    if (!result.handled()) {
        return Optional.empty();
    }
    if (this.controller.setScrollOffsetY(result.scrollOffsetY())) {
        this.onLayoutChanged.run();
    }
    return Optional.of(this);
}

