        if (this.elements.size() > this.clientConfig.getMaxLookupHistoryIngredients()) {
            this.elements.remove(this.elements.size() - 1);
        }
        this.notifyListeners();
        this.save();
    }

    @Override
    public @Unmodifiable List<IElement<?>> getElements() {
        return this.elements.stream().map(IBookmark::getElement).toList();
    }

    @Override
    public boolean containsElement(IElement<?> element) {
        return this.elements.stream().anyMatch(bookmark -> bookmark.getElement() == element);
    }

    @Override
    public void addSourceListChangedListener(IIngredientGridSource.SourceListChangedListener listener) {
        this.listeners.add(listener);
    }
